{
    "metadata": {
        "name": "image-generator-google",
        "displayName": "Google Imagen Generator",
        "description": "Generates images via Google Imagen 4 Fast API.",
        "version": "0.1.0",
        "type": "function",
        "tags": [
            "image",
            "google",
            "imagen"
        ]
    },
    "communication": {
        "input_modes": [
            "text/plain",
            "application/json"
        ],
        "output_modes": [
            "application/json"
        ]
    },
    "configuration": {
        "function": {
            "language": "javascript",
            "timeout_ms": 20000,
            "code": "async function handler(input, ctx) {\\n  const axios = ctx.require(\\"axios\\");\\n  const crypto = ctx.require(\\"crypto\\");\\n\\n  const source = input || {};\\n  const basePrompt = typeof source.prompt === \\"string\\" ? source.prompt : \\"\\";\\n  const prompt =\\n    basePrompt.trim() ||\\n    (typeof source.userMessage === \\"string\\" ? source.userMessage.trim() : \\"\");\\n  if (!prompt) {\\n    throw new Error(\\"prompt is required\\");\\n  }\\n\\n  const rawCount = Number(source.count ?? source.n ?? 1);\\n  const count = Math.max(\\n    1,\\n    Math.min(Number.isFinite(rawCount) ? rawCount : 1, 4)\\n  );\\n\\n  const projectId = ctx.process.env.GOOGLE_PROJECT_ID;\\n  const accessToken = ctx.process.env.GOOGLE_ACCESS_TOKEN;\\n  const location =\\n    ctx.process.env.GOOGLE_REGION && ctx.process.env.GOOGLE_REGION.trim().length\\n      ? ctx.process.env.GOOGLE_REGION.trim()\\n      : \\"us-central1\\";\\n\\n  if (!projectId || !accessToken) {\\n    throw new Error(\\"GOOGLE_PROJECT_ID and GOOGLE_ACCESS_TOKEN required\\");\\n  }\\n\\n  const endpoint = `https://aiplatform.googleapis.com/v1/projects/${projectId}/locations/${location}/publishers/google/models/imagen-4.0-fast-generate-001:predict`;\\n\\n  const response = await axios.post(\\n    endpoint,\\n    {\\n      instances: [{ prompt }],\\n      parameters: { sampleCount: count },\\n    },\\n    {\\n      headers: {\\n        Authorization: `Bearer ${accessToken}`,\\n        \\"Content-Type\\": \\"application/json\\",\\n      },\\n      timeout: 120000,\\n    }\\n  );\\n\\n  const predictions = Array.isArray(response.data?.predictions)\\n    ? response.data.predictions\\n    : [];\\n\\n  if (!predictions.length) {\\n    throw new Error(\\"Google Imagen returned no predictions\\");\\n  }\\n\\n  const attachments = [];\\n  for (let index = 0; index < predictions.length; index++) {\\n    const prediction = predictions[index] || {};\\n    const base64 =\\n      prediction.bytesBase64Encoded ||\\n      prediction.imageBytes ||\\n      prediction.data;\\n    if (!base64 || typeof base64 !== \\"string\\") {\\n      continue;\\n    }\\n\\n    const buffer = Buffer.from(base64, \\"base64\\");\\n    if (!buffer.length) {\\n      continue;\\n    }\\n\\n    const mime =\\n      typeof prediction.mimeType === \\"string\\" && prediction.mimeType.length\\n        ? prediction.mimeType\\n        : \\"image/png\\";\\n    const extension = mime.split(\\"/\\")[1] || \\"png\\";\\n    const hash = crypto.createHash(\\"sha256\\").update(buffer).digest(\\"hex\\");\\n\\n    const asset = await ctx.assets.saveBuffer({\\n      buffer,\\n      mime,\\n      filename: `google-${Date.now()}-${index}.${extension}`,\\n      subpath: \\"generated\\",\\n    });\\n\\n    attachments.push({\\n      assetId: asset.id,\\n      url: `/assets/${asset.id}`,\\n      mime,\\n      size: buffer.length,\\n      hash,\\n      altText: prompt,\\n      provider: \\"google\\",\\n      index,\\n    });\\n  }\\n\\n  if (!attachments.length) {\\n    throw new Error(\\"Failed to generate image attachments\\");\\n  }\\n\\n  const title =\\n    typeof source.title === \\"string\\" && source.title.trim().length\\n      ? source.title.trim()\\n      : \\"Google Imagen Set\\";\\n\\n  const deliverable = await ctx.deliverables.create({\\n    title,\\n    content: `Generated ${attachments.length} image(s) via Google Imagen 4`,\\n    format: attachments[0]?.mime || \\"image/png\\",\\n    type: \\"image\\",\\n    attachments: { images: attachments },\\n    metadata: {\\n      provider: \\"google\\",\\n      model: \\"imagen-4.0-fast\\",\\n      prompt,\\n      count: attachments.length,\\n      location,\\n    },\\n  });\\n\\n  return {\\n    success: true,\\n    provider: \\"google\\",\\n    deliverable,\\n    images: attachments,\\n    metadata: {\\n      prompt,\\n      count: attachments.length,\\n      location,\\n    },\\n  };\\n}\\n\\nmodule.exports = handler;"
        },
        "execution_capabilities": {
            "supports_converse": false,
            "supports_plan": false,
            "supports_build": true
        }
    },
    "prompts": {
        "system": "Generate images via Google Imagen 4 Fast. Optimise prompts for business storytelling and keep metadata concise."
    }
}
